    private static readonly Dictionary<string, JsonObject> ParsedSchemas = new(System.StringComparer.Ordinal);

    /// <summary>The captured schema for a tool, or null when the reference has no such tool.</summary>
    internal static JsonObject? Schema(string name)
    {
        if (!SchemaJson.TryGetValue(name, out var json))
        {
            return null;
        }

        lock (ParsedSchemas)
        {
            if (!ParsedSchemas.TryGetValue(name, out var parsed))
            {
                parsed = (JsonObject)JsonNode.Parse(json)!;
                ParsedSchemas[name] = parsed;
            }

            // Callers get their own copy: a JsonNode has one parent.
            return (JsonObject)parsed.DeepClone();
        }
    }

    /// <summary>The property names the reference's schema declares, in order.</summary>
    internal static IReadOnlyList<string>? PropertyNames(string name)
    {
        var schema = Schema(name);
        return schema?["properties"] is JsonObject props ? [.. props.Select(static p => p.Key)] : null;
    }

    /// <summary>The description for a tool in the given form, or null when the reference has no such tool.</summary>
    internal static string? Description(string name, bool lean) =>
        lean && Lean.TryGetValue(name, out var leanDoc) ? leanDoc
        : Classic.TryGetValue(name, out var doc) ? doc
        : null;
}
